160	        )
161	        port map (
162	            aclr => aclr,
163	
164	            wrclk => write_clk,
165	            data => write_data,
166	            wrreq => write_enable,
167	            wrempty => open,
168	            wrfull => full,
169	            wrusedw => words_stored_slv,
170	
171	            rdclk => read_clk,
172	            q => read_data,
173	            rdreq => read_enable,
174	            rdempty => empty,
175	            rdfull => open,
176	            rdusedw => open -- May not be available
177	        );
