1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     API-style unit tests for the FIFO module.
4	--!
5	--! @license    This project is released under the terms of the MIT License. See LICENSE for more details.
6	--!
7	
8	-- VUnit: run_all_in_same_sim
9	
10	library ieee;
11	use ieee.std_logic_1164.all;
12	use ieee.numeric_std.all;
13	use ieee.math_real.all;
14	
15	library vunit_lib;
16	context vunit_lib.vunit_context;
17	
18	library osvvm;
19	use osvvm.RandomPkg.RandomPType;
20	
21	use work.tb_utils.all;
22	use work.utils_pkg.all;
23	
24	entity tb_fifo_async is
25	    generic (
26	        runner_cfg: string := runner_cfg_default;
27	        tb_path: string
28	    );
29	end entity;
30	
31	architecture tb of tb_fifo_async is
32	    -------------------------------------------------------------
33	    -- Simulation parameters
34	    -------------------------------------------------------------
35	    constant ENABLE_DEBUG_PRINT: boolean := false;
36	    constant SIMULATION_TIMEOUT_TIME: time := 10 ms;
37	    constant DATA_WIDTH: positive := 8;
38	    constant FIFO_DEPTH: positive := 32;
39	    constant CDC_SYNC_STAGES: positive := 2;
40	    -------------------------------------------------------------
41	
42	    -------------------------------------------------------------
43	    -- Clock and Reset
44	    -------------------------------------------------------------
45	    constant WRITE_CLK_FREQUENCY: real := real(50e6);
46	    constant READ_CLK_NORMAL_FREQUENCY: real := real(50e6);
47	    constant READ_CLK_SLOW_FREQUENCY: real := real(25e6);
48	    constant READ_CLK_FAST_FREQUENCY: real := real(100e6);
49	
50	    constant PROPAGATION_TIME: time := 1 ns;
51	
52	    signal fifo_aclr: std_ulogic := '0';
53	    signal write_clk: std_ulogic := '0';
54	    signal clk_read_normal: std_ulogic := '0';
55	    signal clk_read_slow: std_ulogic := '0';
56	    signal clk_read_fast: std_ulogic := '0';
57	    signal active_read_clk: std_ulogic;
58	    -------------------------------------------------------------
59	
60	    -------------------------------------------------------------
61	    -- DUT connections
62	    -------------------------------------------------------------
63	    signal fifo_write_enable: std_ulogic := '0';
64	    signal fifo_write_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0) := (others => '0');
65	    signal fifo_read_enable: std_ulogic := '0';
66	    signal fifo_read_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
67	    signal fifo_read_data_valid: std_ulogic;
68	    signal fifo_empty: std_ulogic;
69	    signal fifo_full: std_ulogic;
70	    signal fifo_words_stored: natural;
71	    -------------------------------------------------------------
72	
73	    -------------------------------------------------------------
74	    -- Testbench Internals
75	    -------------------------------------------------------------
76	    constant WORDS_TO_TEST: natural := 8;
77	
78	    type clk_select_t is (normal, slow, fast);
79	    signal read_clk_select: clk_select_t := normal;
80	
81	    signal write_clk_enable: std_ulogic := '1';
82	    signal clk_read_enable: std_ulogic := '1';
83	
84	    signal simulation_done: boolean := false;
85	    -------------------------------------------------------------
86	
87	    -------------------------------------------------------------
88	    -- Helper procedures
89	    -------------------------------------------------------------
90	    procedure wait_write_clock_cycles(cycles: natural) is
91	    begin
92	        for i in 0 to cycles - 1 loop
93	            wait until rising_edge(write_clk);
94	        end loop;
95	        wait for PROPAGATION_TIME;
96	    end procedure;
97	
98	    procedure wait_read_clock_cycles(cycles: natural) is
99	    begin
100	        for i in 0 to cycles - 1 loop
101	            wait until rising_edge(active_read_clk);
102	        end loop;
103	        wait for PROPAGATION_TIME;
104	    end procedure;
105	    -------------------------------------------------------------
106	begin
107	    -------------------------------------------------------------
108	    -- CLOCK and RESET Generation
109	    -------------------------------------------------------------
110	    generate_advanced_clock(write_clk, WRITE_CLK_FREQUENCY, 0 fs, write_clk_enable);
111	    generate_advanced_clock(clk_read_normal, READ_CLK_NORMAL_FREQUENCY, 0 fs, clk_read_enable);
112	    generate_advanced_clock(clk_read_slow, READ_CLK_SLOW_FREQUENCY, 0 fs, clk_read_enable);
113	    generate_advanced_clock(clk_read_fast, READ_CLK_FAST_FREQUENCY, 0 fs, clk_read_enable);
114	
115	    with read_clk_select select active_read_clk <=
116	        clk_read_normal when normal,
117	        clk_read_slow when slow,
118	        clk_read_fast when fast;
119	    -------------------------------------------------------------
120	
121	    -------------------------------------------------------------
122	    -- VUnit
123	    -------------------------------------------------------------
124	    test_runner_watchdog(runner, SIMULATION_TIMEOUT_TIME);
125	
126	    main: process
127	    begin
128	        test_runner_setup(runner, runner_cfg);
129	        info("Starting tb_fifo_async" & LF);
130	
131	        if ENABLE_DEBUG_PRINT then
132	            show(display_handler, debug);
133	        end if;
134	
135	        wait until simulation_done;
136	        info("Simulation done, all tests passed!" & LF);
137	
138	        test_runner_cleanup(runner);
139	        wait;
140	    end process;
141	    -------------------------------------------------------------
142	
143	     --------------------------------------------------
144	    -- Checker
145	    --------------------------------------------------
146	    checker: process
147	        variable random: RandomPType;
148	        variable write_count, read_count: natural;
149	        variable write_data, expected_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
150	        variable test_data_queue: queue_t;
151	
152	        procedure reset_fifo is begin
153	            if test_data_queue /= null_queue then
154	                flush(queue => test_data_queue);
155	            end if;
156	            test_data_queue := new_queue;
157	
158	            fifo_aclr <= '1';
159	            fifo_write_enable <= '0';
160	            fifo_read_enable <= '0';
161	            wait_write_clock_cycles(5);
162	            wait_read_clock_cycles(5);
163	            fifo_aclr <= '0';
164	            wait_write_clock_cycles(5);
165	            wait_read_clock_cycles(5);
166	        end procedure;
167	
168	        procedure test_basic_operations is begin
169	            info(
170	                "Test 1.0) test_basic_operations: " & LF &
171	                "Tests basic read/write operations across clock domains" & LF
172	            );
173	
174	            read_clk_select <= normal;
175	            reset_fifo;
176	            write_count := 0;
177	            read_count := 0;
178	
179	            -- Check initial conditions
180	            check_equal(got => fifo_empty, expected => '1', msg => "FIFO should be empty after reset");
181	            check_equal(got => fifo_full, expected => '0', msg => "FIFO should not be full after reset");
182	            check_equal(got => fifo_words_stored, expected => 0, msg => "No words should be stored in FIFO after reset");
183	
184	            -- Write some random data to the FIFO
185	            for i in 0 to WORDS_TO_TEST - 1 loop
186	                wait_write_clock_cycles(1);
187	                fifo_write_enable <= '1';
188	                write_data := std_ulogic_vector(to_unsigned(i + 100, DATA_WIDTH));
189	                fifo_write_data <= write_data;
190	                push(queue => test_data_queue, value => write_data);
191	                write_count := write_count + 1;
192	                wait_write_clock_cycles(1);
193	                fifo_write_enable <= '0';
194	                wait_write_clock_cycles(2);
195	            end loop;
196	
197	            -- Allow time for signals to propagate between clock domains
198	            wait_write_clock_cycles(5);
199	            wait_read_clock_cycles(5);
200	
201	            check_equal(got => fifo_empty, expected => '0', msg => "FIFO should not be empty after writes");
202	
203	            -- Read back and verify data
204	            for i in 0 to WORDS_TO_TEST - 1 loop
205	                wait_read_clock_cycles(1);
206	                fifo_read_enable <= '1';
207	
208	                wait until fifo_read_data_valid;
209	                fifo_read_enable <= '0';
210	                expected_data := pop(queue => test_data_queue);
211	                debug("Read data: " & to_string(fifo_read_data) & ", Expected: " & to_string(expected_data));
212	
213	                check_equal(got => fifo_read_data, expected => expected_data, msg => "Data mismatch at index " & to_string(i));
214	                read_count := read_count + 1;
215	                wait_read_clock_cycles(2);
216	            end loop;
217	
218	            check_equal(got => write_count, expected => read_count, msg => "Read count doesn't match write count");
219	            check_equal(got => fifo_empty, expected => '1', msg => "FIFO should be empty after all reads");
220	
221	            info("Test 1.0) Basic operations test completed successfully." & LF);
222	        end procedure;
223	
