324	        procedure test_different_clock_speeds is begin
325	            info(
326	                "Test 4.0) test_different_clock_speeds: " & LF &
327	                "Tests FIFO operation with different read clock frequencies" & LF
328	            );
329	
330	            read_clk_select <= slow;
331	            reset_fifo;
332	
333	            for i in 0 to WORDS_TO_TEST - 1 loop
334	                wait_write_clock_cycles(1);
335	                fifo_write_enable <= '1';
336	                write_data := std_ulogic_vector(to_unsigned(i + 300, DATA_WIDTH));
337	                fifo_write_data <= write_data;
338	                push(queue => test_data_queue, value => write_data);
339	                wait_write_clock_cycles(1);
340	                fifo_write_enable <= '0';
341	                wait_write_clock_cycles(2);
342	            end loop;
343	
344	            info("Testing with random read clock speeds" & LF);
345	
346	            -- Read data with fast read clock
347	            for i in 0 to WORDS_TO_TEST - 1 loop
348	                -- Randomly select a read clock speed
349	                read_clk_select <= clk_select_t'val(random.RandInt(
350	                    Min => clk_select_t'pos(clk_select_t'low),
351	                    Max => clk_select_t'pos(clk_select_t'high)
352	                ));
353	
354	                wait_read_clock_cycles(1);
355	                fifo_read_enable <= '1';
356	
357	                wait until fifo_read_data_valid;
358	                fifo_read_enable <= '0';
359	                expected_data := pop(queue => test_data_queue);
360	                check_equal(
361	                    got => fifo_read_data,
362	                    expected => expected_data,
363	                    msg => "Data mismatch with fast clock at index " & to_string(i)
364	                );
365	                wait_read_clock_cycles(2);
366	            end loop;
367	
368	            info("Test 4.0) Different clock speeds test completed successfully." & LF);
369	        end procedure;
