371	        procedure test_different_clock_domain_combinations is begin
372	            info(
373	                "Test 5.0) test_different_clock_domain_combinations: " & LF &
374	                "Tests FIFO with both fast write/slow read and slow write/fast read" & LF
375	            );
376	
377	            info("Test 5.1) With fast write (100MHz) / slow read (50MHz)" & LF);
378	            read_clk_select <= slow;
379	            reset_fifo;
380	
381	            -- Fill with test pattern
382	            for i in 0 to WORDS_TO_TEST - 1 loop
383	                wait_write_clock_cycles(1);
384	                fifo_write_enable <= '1';
385	                write_data := std_ulogic_vector(to_unsigned(i + 800, DATA_WIDTH));
386	                fifo_write_data <= write_data;
387	                push(queue => test_data_queue, value => write_data);
388	                wait_write_clock_cycles(1);
389	                fifo_write_enable <= '0';
390	                wait_write_clock_cycles(1);
391	            end loop;
392	
393	            -- Verify data with slow reads
394	            for i in 0 to WORDS_TO_TEST - 1 loop
395	                wait_read_clock_cycles(1);
396	                fifo_read_enable <= '1';
397	
398	                wait until fifo_read_data_valid;
399	                fifo_read_enable <= '0';
400	                expected_data := pop(queue => test_data_queue);
401	                check_equal(
402	                    got => fifo_read_data,
403	                    expected => expected_data,
404	                    msg => "Data mismatch with fast write/slow read at index " & to_string(i)
405	                );
406	                wait_read_clock_cycles(2);
407	            end loop;
408	
409	            info("Test 5.2) With slow write (simulated 50MHz) / fast read (200MHz)");
410	            read_clk_select <= fast;
411	            reset_fifo;
412	
413	            -- Fill with test pattern using slower write timing
414	            for i in 0 to WORDS_TO_TEST - 1 loop
415	                wait_write_clock_cycles(1);
416	                fifo_write_enable <= '1';
417	                write_data := std_ulogic_vector(to_unsigned(i + 900, DATA_WIDTH));
418	                fifo_write_data <= write_data;
419	                push(queue => test_data_queue, value => write_data);
420	                wait_write_clock_cycles(1);
421	                fifo_write_enable <= '0';
422	
423	                -- Add extra delay to simulate slower write clock
424	                wait for 20 ns;
425	            end loop;
426	
427	            -- Wait for synchronization
428	            wait_write_clock_cycles(5);
429	            wait_read_clock_cycles(5);
430	
431	            -- Verify data with fast reads
432	            for i in 0 to WORDS_TO_TEST - 1 loop
433	                wait_read_clock_cycles(1);
434	                fifo_read_enable <= '1';
435	
436	                wait until fifo_read_data_valid;
437	                fifo_read_enable <= '0';
438	                expected_data := pop(queue => test_data_queue);
439	                check_equal(
440	                    got => fifo_read_data,
441	                    expected => expected_data,
442	                    msg => "Data mismatch with slow write/fast read at index " & to_string(i)
443	                );
444	                wait_read_clock_cycles(1);  -- Shorter wait since we have fast reads
445	            end loop;
446	
447	            info("Test 5.0) Different clock domain combinations test completed successfully." & LF);
448	        end procedure;
449	
450	        procedure test_reset_behavior is begin
451	            info(
452	                "Test 6.0) test_reset_behavior: " & LF &
453	                "Tests FIFO reset behavior during operation" & LF
454	            );
455	
456	            read_clk_select <= normal;
457	            reset_fifo;
458	
459	            -- Write some data
460	            for i in 0 to 3 loop
461	                wait_write_clock_cycles(1);
462	                fifo_write_enable <= '1';
463	                fifo_write_data <= std_ulogic_vector(to_unsigned(i + 400, DATA_WIDTH));
464	                wait_write_clock_cycles(1);
465	                fifo_write_enable <= '0';
466	                wait_write_clock_cycles(2);
467	            end loop;
468	
469	            wait_write_clock_cycles(5);
470	            check_equal(got => fifo_empty, expected => '0', msg => "FIFO should not be empty after writes");
471	
472	            -- Reset during operation
473	            fifo_aclr <= '1';
474	            wait_write_clock_cycles(5);
475	            wait_read_clock_cycles(5);
476	            fifo_aclr <= '0';
477	            wait_write_clock_cycles(5);
478	            wait_read_clock_cycles(5);
479	
480	            -- Verify state after reset
481	            check_equal(got => fifo_empty, expected => '1', msg => "FIFO should be empty after reset");
482	            check_equal(got => fifo_full, expected => '0', msg => "FIFO should not be full after reset");
483	            check_equal(got => fifo_words_stored, expected => 0, msg => "Words stored should be 0 after reset");
484	
485	            -- Verify normal operation after reset
486	            for i in 0 to 2 loop
487	                wait_write_clock_cycles(1);
488	                fifo_write_enable <= '1';
489	                write_data := std_ulogic_vector(to_unsigned(i + 500, DATA_WIDTH));
490	                fifo_write_data <= write_data;
491	                push(queue => test_data_queue, value => write_data);
492	                wait_write_clock_cycles(1);
493	                fifo_write_enable <= '0';
494	                wait_write_clock_cycles(2);
495	            end loop;
496	
497	            for i in 0 to 2 loop
498	                wait_read_clock_cycles(1);
499	                fifo_read_enable <= '1';
500	
501	                wait until fifo_read_data_valid;
502	                fifo_read_enable <= '0';
503	                expected_data := pop(queue => test_data_queue);
504	                check_equal(
505	                    got => fifo_read_data,
506	                    expected => expected_data,
507	                    msg => "Data mismatch after reset at index " & to_string(i)
508	                );
509	                wait_read_clock_cycles(2);
510	            end loop;
511	
512	            info("Test 6.0) Reset behavior test completed successfully." & LF);
513	        end procedure;
514	
515	        procedure test_reset_during_operations is begin
516	            info(
517	                "Test 7.0) test_reset_during_operations: " & LF &
518	                "Tests reset at various operational points" & LF
519	            );
520	
521	            info("Test 7.1) Reset during write operation" & LF);
522	            read_clk_select <= normal;
523	            reset_fifo;
524	
525	            -- Start a write operation
526	            wait_write_clock_cycles(1);
527	            fifo_write_enable <= '1';
528	            fifo_write_data <= x"EF";
529	
530	            -- Assert reset during write
531	            fifo_aclr <= '1';
532	            wait_write_clock_cycles(1);
533	            fifo_write_enable <= '0';
534	            wait_write_clock_cycles(3);
535	            fifo_aclr <= '0';
536	            wait_write_clock_cycles(5);
537	
538	            -- Verify FIFO is empty and write was not completed
539	            check_equal(got => fifo_empty, expected => '1', msg => "FIFO should be empty after reset during write");
540	            check_equal(got => fifo_words_stored, expected => 0, msg => "Words stored should be 0 after reset during write");
541	
542	            info("Test 7.2) Reset during read operation" & LF);
543	            reset_fifo;
544	
545	            -- Write some data
546	            for i in 0 to 3 loop
547	                wait_write_clock_cycles(1);
548	                fifo_write_enable <= '1';
549	                fifo_write_data <= std_logic_vector(to_unsigned(i + 1000, DATA_WIDTH));
550	                wait_write_clock_cycles(1);
551	                fifo_write_enable <= '0';
552	                wait_write_clock_cycles(2);
553	            end loop;
554	
555	            -- Start a read operation
556	            wait_read_clock_cycles(1);
557	            fifo_read_enable <= '1';
558	
559	            -- Assert reset during read
560	            fifo_aclr <= '1';
561	            wait_read_clock_cycles(1);
562	            fifo_read_enable <= '0';
563	            wait_read_clock_cycles(3);
564	            fifo_aclr <= '0';
565	            wait_read_clock_cycles(5);
566	
567	            -- Verify FIFO is empty and in correct state
568	            check_equal(got => fifo_empty, expected => '1', msg => "FIFO should be empty after reset during read");
569	            check_equal(got => fifo_words_stored, expected => 0, msg => "Words stored should be 0 after reset during read");
570	
571	            info("Test 7.3) Reset when almost full" & LF);
572	            reset_fifo;
573	
574	            -- Fill FIFO to almost full
575	            for i in 0 to FIFO_DEPTH - 2 loop
576	                wait_write_clock_cycles(1);
577	                fifo_write_enable <= '1';
578	                fifo_write_data <= std_logic_vector(to_unsigned(i + 1100, DATA_WIDTH));
579	                wait_write_clock_cycles(1);
580	                fifo_write_enable <= '0';
581	                wait_write_clock_cycles(1);
582	            end loop;
583	
584	            -- Assert reset when almost full
585	            fifo_aclr <= '1';
586	            wait_write_clock_cycles(3);
587	            wait_read_clock_cycles(3);
588	            fifo_aclr <= '0';
589	            wait_write_clock_cycles(5);
590	            wait_read_clock_cycles(5);
591	
592	            -- Verify FIFO is empty and in correct state
593	            check_equal(got => fifo_empty, expected => '1', msg => "FIFO should be empty after reset when almost full");
594	            check_equal(got => fifo_words_stored, expected => 0, msg => "Words stored should be 0 after reset when almost full");
595	
596	            info("Test 7.0) Reset during operations test completed successfully." & LF);
597	        end procedure;
598	
599	        procedure test_simultaneous_read_write is begin
600	            info(
601	                "Test 8.0) test_simultaneous_read_write: " & LF &
602	                "Tests FIFO operation with simultaneous reads and writes" & LF
603	            );
604	
605	            read_clk_select <= normal;
606	            reset_fifo;
607	
608	            -- First fill half the FIFO
609	            for i in 0 to (FIFO_DEPTH / 2) - 1 loop
610	                wait_write_clock_cycles(1);
611	                fifo_write_enable <= '1';
612	                write_data := std_ulogic_vector(to_unsigned(i + 600, DATA_WIDTH));
613	                fifo_write_data <= write_data;
614	                push(queue => test_data_queue, value => write_data);
615	                wait_write_clock_cycles(1);
616	                fifo_write_enable <= '0';
617	                wait_write_clock_cycles(1);
618	            end loop;
619	
620	            wait_write_clock_cycles(5);
621	            wait_read_clock_cycles(5);
622	            check_equal(got => fifo_empty, expected => '0', msg => "FIFO should not be empty after writes");
623	
624	            -- Now perform alternating simultaneous read/write operations
625	            for i in 0 to (FIFO_DEPTH / 2) - 1 loop
626	                wait_write_clock_cycles(1);
627	                fifo_write_enable <= '1';
628	                write_data := std_ulogic_vector(to_unsigned(i + 700, DATA_WIDTH));
629	                fifo_write_data <= write_data;
630	                push(queue => test_data_queue, value => write_data);
631	                wait_read_clock_cycles(1);
632	                fifo_read_enable <= '1';
633	                fifo_write_enable <= '0';
634	
635	                wait until fifo_read_data_valid;
636	                fifo_read_enable <= '0';
637	                expected_data := pop(queue => test_data_queue);
638	                debug("Read data: " & to_string(fifo_read_data) & ", Expected: " & to_string(expected_data));
639	                debug("Words stored: " & to_string(fifo_words_stored));
640	
641	                check_equal(
642	                    got => fifo_read_data,
643	                    expected => expected_data,
644	                    msg => "Data mismatch during simultaneous R/W at index " & to_string(i)
645	                );
646	
647	                -- Check that words_stored remains constant during simultaneous operations
648	                check_equal(
649	                    got => fifo_words_stored = (FIFO_DEPTH / 2) or fifo_words_stored = (FIFO_DEPTH / 2) - 1,
650	                    expected => true,
651	                    msg => "Words stored should be around FIFO_DEPTH / 2 during simultaneous R/W"
652	                );
653	
654	                wait_write_clock_cycles(2);
655	                wait_read_clock_cycles(2);
656	            end loop;
657	
658	            -- Read out remaining words
659	            for i in 0 to (FIFO_DEPTH / 2) - 1 loop
660	                wait_read_clock_cycles(1);
661	                fifo_read_enable <= '1';
662	
663	                wait until fifo_read_data_valid;
664	                fifo_read_enable <= '0';
665	                expected_data := pop(queue => test_data_queue);
666	                check_equal(
667	                    got => fifo_read_data,
668	                    expected => expected_data,
669	                    msg => "Data mismatch when reading remaining words at index " & to_string(i)
670	                );
671	                wait_read_clock_cycles(2);
672	            end loop;
673	
674	            wait_write_clock_cycles(5);
675	            wait_read_clock_cycles(5);
676	            check_equal(got => fifo_empty, expected => '1', msg => "FIFO should be empty after all reads");
677	
678	            info("Test 8.0) Simultaneous read/write test completed successfully." & LF);
679	        end procedure;
680	
681	        procedure test_word_count_accuracy is begin
682	            info(
683	                "Test 9.0) test_word_count_accuracy: " & LF &
684	                "Specifically tests fifo_words_stored accuracy under various conditions" & LF
685	            );
686	
687	            reset_fifo;
688	            check_equal(got => fifo_words_stored, expected => 0, msg => "Words stored should start at zero");
689	
690	            -- Add words one at a time and verify count
691	            for i in 1 to 8 loop
692	                wait_write_clock_cycles(1);
693	                fifo_write_enable <= '1';
694	                fifo_write_data <= std_logic_vector(to_unsigned(i * 100, DATA_WIDTH));
695	                wait_write_clock_cycles(1);
696	                fifo_write_enable <= '0';
697	
698	                wait_write_clock_cycles(5);  -- Allow for synchronization
699	                wait_read_clock_cycles(5);
700	
701	                check_equal(
702	                    got => fifo_words_stored,
703	                    expected => i,
704	                    msg => "Words stored should be " & to_string(i) & " after write #" & to_string(i)
705	                );
706	            end loop;
707	
708	            -- Remove words one at a time and verify count
709	            for i in 7 downto 0 loop
710	                wait_read_clock_cycles(1);
711	                fifo_read_enable <= '1';
712	                wait_read_clock_cycles(1);
713	                fifo_read_enable <= '0';
714	
715	                wait_read_clock_cycles(5);  -- Allow for synchronization
716	
717	                check_equal(
718	                    got => fifo_words_stored,
719	                    expected => i,
720	                    msg => "Words stored should be " & to_string(i) & " after read"
721	                );
722	            end loop;
723	
724	            -- Test rapid alternating writes and reads
725	            info("Test 9.1) Testing word count during alternating writes and reads");
726	            for i in 1 to 5 loop
727	                -- Write
728	                wait_write_clock_cycles(1);
729	                fifo_write_enable <= '1';
730	                fifo_write_data <= std_logic_vector(to_unsigned(i * 200, DATA_WIDTH));
731	                wait_write_clock_cycles(1);
732	                fifo_write_enable <= '0';
733	
734	                wait_write_clock_cycles(3);
735	                wait_read_clock_cycles(3);
736	
737	                -- Read
738	                wait_read_clock_cycles(1);
739	                fifo_read_enable <= '1';
740	                wait_read_clock_cycles(1);
741	                fifo_read_enable <= '0';
742	                wait_read_clock_cycles(3);
743	
744	                -- Should remain at 0 after each read/write pair
745	                check_equal(
746	                    got => fifo_words_stored,
747	                    expected => 0,
748	                    msg => "Words stored should remain 0 after write/read pair #" & to_string(i)
749	                );
750	            end loop;
751	
752	            info("Test 9.0) Word count accuracy test completed successfully." & LF);
753	        end procedure;
754	    begin
755	        random.InitSeed(tb_path & random'instance_name);
756	
757	        wait_write_clock_cycles(1);
758	
759	        while test_suite loop
760	            if run("test_basic_operations") then
761	                test_basic_operations;
762	            elsif run("test_full_flag") then
763	                test_full_flag;
764	            elsif run("test_empty_flag") then
765	                test_empty_flag;
766	            elsif run("test_different_clock_speeds") then
767	                test_different_clock_speeds;
768	            elsif run("test_different_clock_domain_combinations") then
769	                test_different_clock_domain_combinations;
770	            elsif run("test_reset_behavior") then
771	                test_reset_behavior;
772	            elsif run("test_reset_during_operations") then
773	                test_reset_during_operations;
774	            elsif run("test_simultaneous_read_write") then
775	                test_simultaneous_read_write;
776	            elsif run("test_word_count_accuracy") then
777	                test_word_count_accuracy;
778	            else
779	                assert false report "No test has been run!" severity failure;
780	            end if;
781	        end loop;
782	
783	        simulation_done <= true;
784	        wait;
785	    end process;
786	    -------------------------------------------------------------
787	
788	    -------------------------------------------------------------
789	    -- Instantiate module to test
790	    -------------------------------------------------------------
791	    DuT: entity work.fifo_async(own_behavioural_async_fifo)
792	        generic map (
793	            FIFO_DEPTH_IN_BITS => to_bits(FIFO_DEPTH),
794	            CDC_SYNC_STAGES => CDC_SYNC_STAGES
795	        )
796	        port map (
797	            aclr => fifo_aclr,
798	            write_clk => write_clk,
799	            read_clk => active_read_clk,
800	            write_enable => fifo_write_enable,
801	            write_data => fifo_write_data,
802	            read_enable => fifo_read_enable,
803	            read_data => fifo_read_data,
804	            read_data_valid => fifo_read_data_valid,
805	            full => fifo_full,
806	            empty => fifo_empty,
807	            words_stored => fifo_words_stored
808	        );
809	    -------------------------------------------------------------
810	end architecture;
